/**
 * Bounded JSON scalar, not executable content. Strings at most 4096 code points; finite numbers in the JSON-safe
 * range.
 */
export type UIStreamScalar = null | boolean | number | string;

/**
 * Interaction value: scalar, scalar array or scalar map only (one container level). No functions, callbacks, binary
 * data or nested containers. Never send credentials or secret field contents.
 */
export type UIStreamValue = UIStreamScalar | UIStreamScalar[] | Record<string, UIStreamScalar>;

/**
 * Client opt-in for protocol 1 plus supported native component tags. ui_version alone does not opt in. Declaration is
 * not runtime support.
 */
export interface UIStreamCapability {
  protocol: 1;
  components: string[];
}

/**
 * Full authoritative tree before deltas, including after resume or recovery. Keys required on sections/items; tiles
 * and global uniqueness need semantic validation.
 */
export interface UIStreamSnapshot {
  protocol: 1;
  session: string;
  epoch: string;
  version: number;
  root_key: string;
  view: View;
}

/**
 * Atomic batch, at most 256 operations. An explicit empty batch keeps the version for a non-event no-op or advances
 * exactly one revision as an accepted or ambiguous callback fence. Validate against a staged whole tree before
 * committing. Ordering/equality are reducer checks.
 */
export interface UIStreamDelta {
  protocol: 1;
  session: string;
  epoch: string;
  base_version: number;
  version: number;
  operations: UIStreamOperation[];
}

/**
 * Authenticated owner interaction for the displayed generation/version. Deduplicate event_id before writes. Validate
 * action against the saved node/event slot, then resolve its callback server-side; no callback code or secrets in
 * this payload.
 */
export interface UIStreamEvent {
  protocol: 1;
  session: string;
  epoch: string;
  version: number;
  event_id: string;
  key: string;
  /**
   * Opaque registered callback Action.id for this node and event slot; never callback code or an authority claim.
   */
  action: string;
  event: string;
  value: UIStreamValue;
}

/**
 * Atomic native tree operation. Unknown operations invalidate the entire batch and require a snapshot, never
 * skipping. Tiles update by replacing their containing grid/carousel.
 */
export type UIStreamOperation =
  | UIStreamReplace
  | UIStreamInsert
  | UIStreamRemove
  | UIStreamMove;
export const UISTREAM_OPERATION_OPS = ["replace", "insert", "remove", "move"] as const;

/**
 * Replace a complete node/subtree; omitted properties are cleared. Exactly one payload, matching the target kind and
 * key.
 */
export type UIStreamReplace = {
  op: "replace";
  key: string;
} & (
  | { view: View; section?: never; item?: never }
  | { view?: never; section: Section; item?: never }
  | { view?: never; section?: never; item: Component }
);

/**
 * Insert a section under root or item under section. before names a destination sibling; omitted means append.
 */
export type UIStreamInsert = {
  op: "insert";
  parent: string;
  before?: string;
} & (
  | { section: Section; item?: never }
  | { section?: never; item: Component }
);

/**
 * Remove a node and its subtree, never the root. Existence/root checks are semantic.
 */
export interface UIStreamRemove {
  op: "remove";
  key: string;
}

/**
 * Move a section/item subtree. No cycles, tile moves or wrong parent kinds. Omitted before appends.
 */
export interface UIStreamMove {
  op: "move";
  key: string;
  parent: string;
  before?: string;
}

/**
 * Owner-bound lifecycle request over the authenticated WebSocket. The transport supplies principal/hub identity;
 * never trust an owner field from JSON. No endpoint or runtime is enabled by these contracts.
 */
export type UIStreamRequest =
  | UIStreamOpenRequest
  | UIStreamCloseRequest
  | UIStreamSuspendRequest
  | UIStreamResumeRequest
  | UIStreamEventRequest
  | UIStreamSnapshotRequest;
export const UISTREAM_REQUEST_REQUESTS = ["open", "close", "suspend", "resume", "event", "snapshot"] as const;

/**
 * Reauthorize the extension/contribution and explicit context.stream capability; allocate an owner-bound session and
 * send a snapshot before deltas.
 */
export interface UIStreamOpenRequest {
  request: "open";
  protocol: 1;
  request_id: string;
  extension: string;
  contribution: string;
  context: UIContext;
  state: string;
}

/**
 * Idempotent for unknown/already closed owned sessions; unmount and release state, callbacks and effects.
 */
export interface UIStreamCloseRequest {
  request: "close";
  protocol: 1;
  request_id: string;
  session: string;
  epoch: string;
}

/**
 * Stop UI intervals/polling and bound pending work. Service work is independent of visibility.
 */
export interface UIStreamSuspendRequest {
  request: "suspend";
  protocol: 1;
  request_id: string;
  session: string;
  epoch: string;
}

/**
 * Reauthorize the owned session, discard stale delta chains and send a fresh snapshot before further deltas.
 */
export interface UIStreamResumeRequest {
  request: "resume";
  protocol: 1;
  request_id: string;
  session: string;
  epoch: string;
  version: number;
}

/**
 * Authorize and deduplicate the interaction before invoking its registered server-side callback. request_id is
 * correlation, not write deduplication.
 */
export interface UIStreamEventRequest {
  request: "event";
  protocol: 1;
  request_id: string;
  interaction: UIStreamEvent;
}

/**
 * Read-only recovery request: reauthorize and send a complete snapshot, never replay an interaction or write.
 */
export interface UIStreamSnapshotRequest {
  request: "snapshot";
  protocol: 1;
  request_id: string;
  session: string;
  epoch: string;
  version: number;
}

export type UIStreamClientEnvelope = {
  type: "extension_ui_stream";
  manager?: string;
} & (
  | { request: UIStreamRequest }
);

/**
 * Bounded presentation-only subset of native ActionResult, at most 64 KiB UTF-8 JSON. Carried in the correlated event
 * receipt and cached on replay. Clients apply it once per session/epoch/event_id, only after reaching
 * receipt.version; never execute HTML, JavaScript or infer authorization from a result. JSX state owns view/items
 * updates through snapshots/deltas. Manager validates push ownership and credential-free HTTPS (or its own permitted
 * native URL).
 */
export interface UIStreamActionResult {
  toast?: string;
  open_url?: string;
  push?: UIStreamPush;
  pop?: boolean;
  lines?: UIStreamFileLines;
}

/**
 * Extension-owned native Push only: no assistant page or arbitrary target. State is additionally bounded to 16 KiB
 * UTF-8. Not authority to invoke an action.
 */
export interface UIStreamPush {
  ui?: string;
  state?: string;
  title?: string;
}

/**
 * Native FileLines presentation response correlated to the saved event, not filesystem access or code execution. The
 * complete result remains limited to 64 KiB UTF-8 JSON.
 */
export interface UIStreamFileLines {
  path: string;
  side?: DiffSide;
  start: number;
  lines: string[];
  total?: number;
}

export interface UIStreamReceipt {
  session: string;
  epoch: string;
  event_id: string;
  version: number;
  status: string;
  result?: UIStreamActionResult;
}

export interface UIStreamFailure {
  code: string;
  message: string;
}

export interface UIStreamSnapshotEnvelope {
  kind: "snapshot";
  type: "extension_ui_stream";
  request_id?: string;
  manager?: string;
  snapshot: UIStreamSnapshot;
}

export interface UIStreamDeltaEnvelope {
  kind: "delta";
  type: "extension_ui_stream";
  request_id?: string;
  manager?: string;
  delta: UIStreamDelta;
}

export interface UIStreamReceiptEnvelope {
  kind: "receipt";
  type: "extension_ui_stream";
  request_id?: string;
  manager?: string;
  receipt: UIStreamReceipt;
}

export interface UIStreamErrorEnvelope {
  kind: "error";
  type: "extension_ui_stream";
  request_id?: string;
  manager?: string;
  error: UIStreamFailure;
}

export interface UIStreamClosedEnvelope {
  kind: "closed";
  type: "extension_ui_stream";
  request_id?: string;
  manager?: string;
  session: string;
}

export type UIStreamServerEnvelope =
  | UIStreamSnapshotEnvelope
  | UIStreamDeltaEnvelope
  | UIStreamReceiptEnvelope
  | UIStreamErrorEnvelope
  | UIStreamClosedEnvelope
  | UIStreamSuspendedEnvelope;
export const UISTREAM_SERVER_ENVELOPE_KINDS = ["snapshot", "delta", "receipt", "error", "closed", "suspended"] as const;

export interface UIStreamSuspendedEnvelope {
  kind: "suspended";
  type: "extension_ui_stream";
  request_id?: string;
  manager?: string;
  session: string;
}

/**
 * Source-process native render revision, independent of manager-owned wire revisions. Validate original JSON before
 * fitting; never trust source recipients or owners.
 */
export interface UIPageSnapshot {
  generation: string;
  version: number;
  rootKey: string;
  view: View;
}
